class Ledger
  def initialize(entries = [])
    @entries = entries.dup
    @frozen = false
  end

  def add(entry)
    raise FrozenError, "Cannot add to a frozen ledger" if @frozen
    @entries << entry
    self
  end

  def entries
    @entries.dup
  end

  def freeze
    raise FrozenError, "Already frozen" if @frozen
    @frozen = true
    @entries = @entries.dup
    @entries.freeze
    self
  end

  def frozen?
    @frozen
  end

  def dup
    Ledger.new(@entries.dup)
  end

  def clone
    Ledger.new(@entries.dup).freeze
  end

  private

  def method_missing(name, *args, &block)
    super
  end

  def respond_to_missing?(name, include_private = false)
    super
  end
end
